    /**
     * Build a facade for {@code config}, loading whatever the enabled stages need.
     *
     * Auditing uses the default InMemoryAuditStore when enabled. State is lost on
     * drop; use with_stores(Self.with_stores) and pass a FileAuditStore when
     * the audit record must survive a restart.
     * {@literal @}throws Exception Returns HaciendaError.Pii if the detection pipeline cannot be built —
     * most often because a model is enabled that this build cannot load.
     *
     * FileAuditStore: crate.audit.FileAuditStore
     */
    public static HaciendaFacade create(final HaciendaConfig config) throws HaciendaRsException {
        java.util.Objects.requireNonNull(config, "config must not be null");
        try (Arena arena = Arena.ofShared()) {
MemorySegment cConfig = MemorySegment.NULL;            Throwable operationFailure = null;
            try {
            String cConfigJson = STREAM_MAPPER.writeValueAsString(config);
            var cConfigJsonSeg = arena.allocateFrom(cConfigJson);
cConfig = (MemorySegment) NativeLib.HACIENDA_HACIENDA_CONFIG_FROM_JSON.invoke(cConfigJsonSeg);
            if (cConfig.equals(MemorySegment.NULL)) { checkLastFfiError(); throw new HaciendaRsException("create: failed to marshal config", (Throwable) null); }
            var handle = (MemorySegment) NativeLib.HACIENDA_HACIENDA_FACADE_NEW.invoke(cConfig);
            if (handle == null || handle.equals(MemorySegment.NULL)) {
                throw new HaciendaRsException("create returned null", (Throwable) null);
            }
            return new HaciendaFacade(handle);
            } catch (Throwable failure) {
                operationFailure = failure;
                throw failure;
            } finally {
                var cleanupFailures = new CleanupFailures();
                cleanupFailures.release(cConfig, handle -> NativeLib.HACIENDA_HACIENDA_CONFIG_FREE.invoke(handle));
                cleanupFailures.throwIfAny(operationFailure);
            }
        }
        catch (Throwable e) {
            if (e instanceof HaciendaRsException) throw (HaciendaRsException) e;
            throw new RuntimeException("create failed: " + e.getMessage(), e);
        }
    }
    /**
     * Build a facade that can mint and reverse pseudonym tokens.
     *
     * Required when the PII configuration selects
     * RedactionMode.Pseudonymize(crate.redaction.RedactionMode.Pseudonymize).
     * HaciendaFacade.new passes no resolver and therefore *fails* for that mode; it
     * does not fall back to masking, because that would apply a weaker control than the
     * one the operator configured.
     *
     * The active key comes from
     * RedactionConfig.key_id(crate.redaction.RedactionConfig.key_id) when set and
     * from the resolver's own notion of "active" otherwise — resolved independently per
     * tenant (P3a), the first time each tenant's pipeline is built. {@code retired} names keys
     * that are no longer minted under but whose existing tokens must stay revealable for
     * every tenant; they are resolved eagerly as part of building each tenant's
     * Pseudonymiser, so a missing one is an error at that point rather than a
     * surprise during a right-of-access request.
     *
     * {@code resolver} is now {@code Arc}-wrapped rather than borrowed (P3a): the facade must be
     * able to call it again lazily, on a later request, for a tenant it has not seen
     * yet — not just once at construction, as before. The default tenant's pipeline is
     * still built eagerly here, so a bad key configuration for that tenant remains a
     * startup error exactly as it was before this change.
     * {@literal @}throws Exception As HaciendaFacade.new, plus
     * HaciendaError.Pii wrapping a key resolution failure for the default tenant.
     */
    public static HaciendaFacade withKeyResolver(
        final HaciendaConfig config,
        final KeyResolver resolver,
        final List<KeyId> retired
    ) throws HaciendaRsException {
        java.util.Objects.requireNonNull(config, "config must not be null");
        java.util.Objects.requireNonNull(resolver, "resolver must not be null");
        java.util.Objects.requireNonNull(retired, "retired must not be null");
        throw new HaciendaRsException("withKeyResolver: unsupported parameter retired", (Throwable) null);
    }

    @Override
    @SuppressWarnings("PMD.AvoidCatchingGenericException")
    public synchronized void close() {
        if (transferPending) {
            awaitTransfer();
        }
        if (handleUnavailable || handle == null || handle.equals(MemorySegment.NULL)) {
            handleUnavailable = true;
            return;
        }
        handleUnavailable = true;
        awaitBorrowedCalls();
        MemorySegment handleToFree = handle;
        handle = MemorySegment.NULL;
        try {
            NativeLib.HACIENDA_HACIENDA_FACADE_FREE.invoke(handleToFree);
        } catch (Throwable e) {
            throw new RuntimeException("Failed to free HaciendaFacade: " + e.getMessage(), e);
        }
    }

    private void awaitTransfer() {
        boolean interrupted = false;
        while (transferPending) {
            try {
                wait();
            } catch (InterruptedException ignored) {
                interrupted = true;
            }
        }
        if (interrupted) {
            Thread.currentThread().interrupt();
        }
    }

    // CPD-OFF — generated FFI boilerplate, identical across all opaque types by design.
    private static void checkLastFfiError() throws HaciendaRsException {
        try {
            int code = (int)(long) NativeLib.HACIENDA_LAST_ERROR_CODE.invoke();
            if (code == 0) { return; }
            MemorySegment ctxPtr = (MemorySegment) NativeLib.HACIENDA_LAST_ERROR_CONTEXT.invoke();
            String msg = ctxPtr.equals(MemorySegment.NULL) ? "unknown" : ctxPtr.reinterpret(Long.MAX_VALUE).getString(0);
            throw NativeLib.lastErrorException(code, msg);
        } catch (HaciendaRsException e) {
            throw e;
        } catch (Throwable e) {
            throw new HaciendaRsException("failed to read last error", e);
        }
    }
    private static final ObjectMapper STREAM_MAPPER = createStreamMapper();

    private static ObjectMapper createStreamMapper() {
        var mapper = new ObjectMapper()
            .registerModule(new com.fasterxml.jackson.datatype.jdk8.Jdk8Module())
            .findAndRegisterModules()
            .setPropertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE)
            .setSerializationInclusion(com.fasterxml.jackson.annotation.JsonInclude.Include.NON_NULL)
            .configure(com.fasterxml.jackson.databind.MapperFeature.ACCEPT_CASE_INSENSITIVE_ENUMS, true);
        return JsonMapperFactory.withNativePathSerialization(mapper);
    }    // CPD-ON
